// Datums in innerText als "VR 12 JUN /20:00", titel staat er 1-6 regels boven
const lines = document.body.innerText.split('\n').filter(l => l.trim().length > 2);
const dateRe = /^(MA|DI|WO|DO|VR|ZA|ZO)\s+\d{1,2}\s+(JAN|FEB|MRT|APR|MEI|JUN|JUL|AUG|SEP|OKT|NOV|DEC)/i;
const events = [];
for (let i = 2; i < lines.length; i++) {
  if (dateRe.test(lines[i].trim())) {
    for (let j = i-1; j >= Math.max(0, i-6); j--) {
      const c = lines[j].trim();
      if (c.length > 4 && !dateRe.test(c) && c !== 'TICKETS' && !/^[\u20ac\d]/.test(c) && !/UITVERKOCHT|GEANNULEERD|BESTELLEN/i.test(c)) {
        events.push({title: c, date_raw: lines[i].trim()}); break;
      }
    }
  }
}
JSON.stringify(events);

