import requests, re, html
def parse_dd_mm_yyyy(s):
    m = re.match(r'(\d{2})-(\d{2})-(\d{4})\s*:', s.strip())
    if m:
        from datetime import date
        return date(int(m.group(3)), int(m.group(2)), int(m.group(1))).isoformat(), re.sub(r'^\d{2}-\d{2}-\d{4}\s*:\s*','',s).strip()
    return None, s.strip()
for pg in range(1, 10):
    r = requests.get(f"https://ontdekpoort.nl/wp-json/wp/v2/event?per_page=100&page={pg}&_fields=title,link")
    if r.status_code != 200: break
    for item in r.json():
        raw = html.unescape(item['title']['rendered'])
        dt, title = parse_dd_mm_yyyy(raw)

